/**
 * Advanced Custom Fields beyond plain collection fields: flexible content → sections (pages and collection entries),
 * repeaters with link and group sub-fields, links, ACF on pages and posts, options pages (definitions, values from a
 * database backup, report). Synthetic site: test/fixtures/acf/site.json (generated by test/fixtures/acf/generate.mjs).
 * Goldens: test/golden/acf/*.json (regenerate after an intended change: UPDATE_GOLDEN=1 pnpm test).
 */
import { existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { importOptions } from "../src/commands/import-options.js";
import { overridesSchema } from "../src/config/overrides.js";
import { kitConfigSchema } from "../src/config/schema.js";
import { sitePaths } from "../src/core/paths.js";
import { Keys } from "../src/ir/portable-text.js";
import type { IrPage } from "../src/ir/schema.js";
import { runTransform } from "../src/phases/transform.js";
import { buildSeed, seedMediaResolver } from "../src/scaffold/seed.js";
import { acfOptionsPlan, acfReport } from "../src/transform/acf.js";
import { flexibleSections, layoutType } from "../src/transform/acf-flexible.js";
import { collectionFields, type CptPlan } from "../src/transform/cpt.js";
import { acfFromMeta, acfGroupsFromExport, acfGroupsFromPosts, acfLocationOptionsPages, acfLocationPostTypes, mapField, type WpFieldDef } from "../src/transform/cpt-fields.js";

const fxDir = join(import.meta.dirname, "fixtures", "acf");
const fx = JSON.parse(readFileSync(join(fxDir, "site.json"), "utf8"));
const goldenDir = join(import.meta.dirname, "golden", "acf");
const golden = (name: string, value: unknown) => {
	const file = join(goldenDir, name);
	const json = `${JSON.stringify(value, null, "\t")}\n`;
	if (process.env.UPDATE_GOLDEN === "1" || !existsSync(file)) {
		mkdirSync(goldenDir, { recursive: true });
		writeFileSync(file, json);
	}
	expect(json).toBe(readFileSync(file, "utf8"));
};

const dir = mkdtempSync(join(tmpdir(), "wp2e-acf-"));
const put = (file: string, data: unknown) => {
	mkdirSync(join(file, ".."), { recursive: true });
	writeFileSync(file, typeof data === "string" ? data : JSON.stringify(data));
};
const config = kitConfigSchema.parse({ slug: "acf", name: "Example Agency", source: { url: "https://acf.example.test" }, target: { productionUrl: "https://acf.example.test" } });

function workspace(name: string, overrides?: string, opts: { options?: boolean } = {}) {
	const paths = sitePaths(name, dir);
	put(join(paths.raw, "extract.json"), {});
	put(join(paths.raw, "exporter", "options.json"), fx.options);
	put(join(paths.raw, "exporter", "content", "page.json"), fx.pages);
	put(join(paths.raw, "exporter", "content", "post.json"), fx.posts);
	put(join(paths.raw, "exporter", "content", "project.json"), fx.project);
	put(join(paths.raw, "exporter", "content", "acf-field-group.json"), fx.acfFieldGroups);
	put(join(paths.raw, "exporter", "content", "acf-field.json"), fx.acfFields);
	put(join(paths.raw, "exporter", "taxonomies.json"), fx.taxonomies);
	put(join(paths.raw, "exporter", "analyze.json"), fx.analyze);
	put(join(paths.raw, "exporter", "types.json"), fx.types);
	for (const [f, d] of Object.entries(fx.fieldDefinitions)) put(join(paths.raw, "field-definitions", f), d);
	if (opts.options !== false) put(join(paths.raw, "acf-options.json"), fx.acfOptions);
	put(join(paths.raw, "media-manifest.json"), fx.media);
	put(join(paths.snapshot, "urls.json"), fx.urls);
	put(join(paths.snapshot, "discovery.json"), fx.discovery);
	if (overrides) put(paths.overrides, overrides);
	return paths;
}
const run = (paths: ReturnType<typeof sitePaths>) => runTransform({ config, paths, reporter: { runId: "t", emit: () => {} } });
const DECIDED = `export default { acfLayouts: { latest_work: "skip" } };\n`;
const readJson = (f: string) => JSON.parse(readFileSync(f, "utf8"));
const readDir = (d: string) => (existsSync(d) ? Object.fromEntries(readdirSync(d).sort().map((f) => [f, readJson(join(d, f))])) : {});

describe("ACF definitions", () => {
	it("flexible content layouts from ACF's own field posts (parent_layout) and from an export file", () => {
		const groups = acfGroupsFromPosts(fx.acfFieldGroups, fx.acfFields);
		const flex = groups[0]?.fields[0];
		expect(flex).toMatchObject({ name: "page_sections", type: "flexible_content" });
		expect(flex?.layouts?.map((l) => `${l.name}: ${l.subFields.map((s) => `${s.name}(${s.type}${s.subFields ? `: ${s.subFields.map((x) => x.name).join(",")}` : ""})`).join(" ")}`)).toEqual([
			"hero: title(text) subtitle(text) image(image) button(link)",
			"text_image: heading(text) content(wysiwyg) image(image) image_position(select)",
			"features: heading(text) cards(repeater: title,text,icon,link)",
			"faq: heading(text) items(repeater: question,answer)",
			"testimonials: heading(text) quotes(repeater: quote,name,role)",
			"text_block: content(wysiwyg)",
			"latest_work: projects(relationship) style(select)",
		]);
		// A front-page location rule assigns the group to pages.
		expect(groups[1]).toMatchObject({ title: "Home extras", postTypes: ["page"], fields: [{ name: "hero_note" }] });
		const exported = acfGroupsFromExport(fx.fieldDefinitions["acf-project.json"].data, "x");
		expect(exported.find((g) => g.title === "Project")?.fields.find((f) => f.name === "blocks")?.layouts?.map((l) => l.name)).toEqual(["gallery_block", "quote", "map_block"]);
		expect(exported.find((g) => g.title === "Site settings")).toMatchObject({ postTypes: [], optionsPages: ["site-settings"] });
	});
	it("location rules: post types, page and post rules, options pages", () => {
		const loc = [[{ param: "page_template", operator: "==", value: "templates/landing.php" }], [{ param: "post_category", operator: "==", value: "category:news" }], [{ param: "post_type", operator: "!=", value: "product" }], [{ param: "options_page", operator: "==", value: "theme-settings" }]];
		expect(acfLocationPostTypes(loc)).toEqual(["page", "post"]);
		expect(acfLocationOptionsPages(loc)).toEqual(["theme-settings"]);
	});
	it("repeater rows flatten links and groups; a top-level link is a URL and its text", () => {
		const def = acfGroupsFromExport(fx.fieldDefinitions["acf-project.json"].data, "x")[0]?.fields.find((f) => f.name === "milestones") as WpFieldDef;
		const [m] = mapField(def, { collectionFor: () => undefined, taken: new Set() });
		expect(m?.type).toBe("repeater");
		expect(m?.subFields?.map((s) => `${s.slug}:${s.type}${s.wpPath ? `@${s.wpPath.join(".")}` : ""}`)).toEqual(["title:string", "due:datetime", "link:url@link.url", "link_label:string@link.title", "details_budget:number@details.budget", "details_owner:string@details.owner"]);
		expect(mapField({ source: "acf", name: "cta", label: "CTA", type: "link" }, { collectionFor: () => undefined, taken: new Set() }).map((f) => `${f.slug}:${f.type}:${f.wp.path?.join(".")}`)).toEqual(["cta:url:cta.url", "cta_label:string:cta.title"]);
	});
});

describe("ACF values from post meta", () => {
	const groups = acfGroupsFromPosts(fx.acfFieldGroups, fx.acfFields);
	const flex = groups[0]?.fields[0] as WpFieldDef;
	it("flexible content rows: layout order from the serialized list, disabled rows left out", () => {
		const rows = acfFromMeta(flex, fx.pages[0].meta) as Record<string, unknown>[];
		expect(rows.map((r) => r.acf_fc_layout)).toEqual(["hero", "text_image", "features", "faq", "testimonials"]);
		expect(rows[2]).toMatchObject({ heading: "What we do", cards: [{ title: "Brand", icon: "53" }, { title: "Web" }, { title: "Print" }] });
	});
	it("layout names → section types", () => {
		expect(["hero", "text_image", "features", "faq", "testimonials", "text_block", "logo_carousel", "two_column", "call_to_action", "stats_row", "anything"].map((n) => layoutType(n) ?? "-")).toEqual(["hero", "media_text", "feature_grid", "faq", "testimonials", "rich_text", "logo_strip", "feature_grid", "cta_banner", "stats", "-"]);
	});
	it("rows → sections (golden): every layout of the home page maps, the disabled row is counted", () => {
		const ctx = { mediaIdForUrl: () => undefined, href: (u: string) => u.replace("https://acf.example.test", ""), keys: new Keys("t_"), decisions: {} };
		const out = flexibleSections(flex, acfFromMeta(flex, fx.pages[0].meta), ctx, { path: "acf", disabled: 1 });
		expect(out.unmapped).toEqual([]);
		expect(out.sections.map((s) => s.type)).toEqual(["hero", "media_text", "feature_grid", "faq", "testimonials"]);
		golden("home-sections.json", out);
	});
	it("a layout that fills no section is unmapped; overrides force or skip it", () => {
		const ctx = { mediaIdForUrl: () => undefined, href: (u: string) => u, keys: new Keys("t_"), decisions: {} };
		const rows = fx.pages[1].acf.page_sections;
		const out = flexibleSections(flex, rows, ctx);
		expect(out.sections.map((s) => s.type)).toEqual(["rich_text"]);
		expect(out.unmapped).toEqual([rows[1]]);
		expect(out.layouts.find((l) => l.layout === "latest_work")).toMatchObject({ by: "unmapped", rows: 1 });
		const skipped = flexibleSections(flex, rows, { ...ctx, decisions: { latest_work: "skip" } });
		expect(skipped.unmapped).toEqual([]);
		expect(skipped.layouts.find((l) => l.layout === "latest_work")?.by).toBe("skip");
		const forced = flexibleSections(flex, [{ acf_fc_layout: "text_block", content: "<h3>Big</h3><p>Words</p>" }], { ...ctx, decisions: { text_block: "cta_banner" } });
		expect(forced.sections[0]).toMatchObject({ type: "cta_banner" });
		expect(forced.layouts[0]?.by).toBe("override");
	});
});

describe("ACF transform", () => {
	it("pages: flexible content becomes the page's sections; an unmapped layout blocks until decided", async () => {
		const open = await run(workspace("open"));
		expect(open.find((c) => c.id === "unmapped")).toMatchObject({ ok: false });
		expect(open.find((c) => c.id === "unmapped")?.detail).toMatch(/latest_work/);
		const paths = workspace("decided", DECIDED);
		const checks = await run(paths);
		for (const id of ["unmapped", "ir-valid", "content-types-handled", "cpt-fields"]) expect(checks.find((c) => c.id === id), id).toMatchObject({ ok: true });
		const home = readJson(join(paths.ir, "pages", "home.json")) as IrPage;
		// Every row mapped: built from them, not from the rendered page.
		expect(home.source.builder).toBe("empty");
		expect(home.sections.map((s) => `${s.type}:${s.sourceRef.adapter}`)).toEqual(["hero:acf", "media_text:acf", "feature_grid:acf", "faq:acf", "testimonials:acf"]);
		expect(home.sections[0]).toMatchObject({ fields: { media: { wpId: 51 }, buttons: [{ label: "See our work", href: "/work/" }] } });
		expect(home.sections[1]).toMatchObject({ fields: { mediaSide: "left", media: [{ wpId: 52 }] } });
		expect(home.diagnostics.map((d) => d.message).join("\n")).toMatch(/1 row\(s\) disabled in ACF/);
		expect(home.diagnostics.find((d) => /hero_note/.test(d.message))).toMatchObject({ level: "warn", code: "lossy" });
		const about = readJson(join(paths.ir, "pages", "about.json")) as IrPage;
		expect(about.sections.map((s) => s.type)).toEqual(["rich_text", "rich_text"]);
		const post = readJson(join(paths.ir, "posts", "hello.json")) as IrPage;
		expect(post.diagnostics.find((d) => /reading_time/.test(d.message))).toMatchObject({ level: "warn" });
	});

	it("collection entries: repeaters, groups, links, flexible content as sections + the rest as data (golden)", async () => {
		const paths = workspace("cpt", DECIDED);
		await run(paths);
		const plan = readJson(join(paths.ir, "collections.json")) as CptPlan;
		const project = plan.collections.find((c) => c.type === "project") as CptPlan["collections"][number];
		expect(project.core.sections).toBe(true);
		expect(project.unknownMeta).toEqual([]);
		expect(collectionFields(project, ["section_hero"]).map((f) => `${f.slug}:${f.type}`)).toEqual(["title:string", "content:blocks", "cover:image", "summary:portableText", "wp_status:select", "featured:boolean", "services:multiSelect", "launched_at:datetime", "opening_time:string", "website:url", "website_label:string", "brochure:file", "lead_page:reference", "related_projects:reference", "contact_email:string", "contact_phone:string", "milestones:repeater", "blocks:json"]);
		const entries = readDir(join(paths.ir, "entries", "project")) as Record<string, IrPage>;
		const harbor = entries["harbor-rebrand.json"] as IrPage;
		expect(harbor.entry?.fields).toMatchObject({ wp_status: "live", featured: true, services: ["brand", "web"], launched_at: "2024-06-01T09:30:00.000Z", opening_time: "09:00:00", website: "https://harbor.example.org/", website_label: "Visit the site", brochure: { wpId: 60, kind: "file" }, contact_email: "hi@harbor.example.org", milestones: [{ title: "Kickoff", due: "2024-01-05T00:00:00.000Z", link: "/notes/", link_label: "Notes", details_budget: 1000, details_owner: "Sam" }, { title: "Launch", due: "2024-06-01T00:00:00.000Z", details_budget: 5000, details_owner: "Alex" }] });
		expect(harbor.entry?.fields.blocks).toBeUndefined();
		expect(harbor.entry?.references).toEqual({ lead_page: ["page:11"], related_projects: ["project:202"] });
		expect(harbor.sections.map((s) => s.type)).toEqual(["gallery", "rich_text", "map"]);
		const city = entries["city-site.json"] as IrPage;
		// get_fields() formats repeater dates for display: the stored meta wins.
		expect(city.entry?.fields.milestones).toEqual([{ title: "Discovery", due: "2025-01-10T00:00:00.000Z" }]);
		// A layout no definition describes stays in the field as data.
		expect(city.entry?.fields.blocks).toEqual([{ acf_fc_layout: "poll_widget", question: "Which colour?" }]);
		golden("collections.json", plan);
		golden("entries.json", entries);
		const md = readFileSync(join(paths.reports, "transform", "coverage.md"), "utf8");
		const acfLines = md.slice(md.indexOf("## ACF flexible content")).split("\n");
		golden("coverage-acf.md.json", acfLines.slice(0, acfLines.findIndex((l) => /^## (?!ACF)/.test(l))));
		// The seed carries the collection's sections and its fields.
		const pages = Object.values(readDir(join(paths.ir, "pages"))) as IrPage[];
		const seed = buildSeed({ name: "x", site: { version: 1, title: "Example Agency", menus: [], partials: [], popups: [] }, pages, partials: [], popups: [], media: seedMediaResolver(new Map(fx.media.map((m: { id: number; url: string }) => [m.id, { url: m.url }])), (u) => u), titleSeparator: "-", forms: [], includeContent: true, collections: { plan, entries: Object.values(entries) } });
		const harborSeed = (seed.content as Record<string, { id: string; data: Record<string, unknown> }[]>).project?.find((e) => e.id === "project:201");
		expect((harborSeed?.data.content as { _type: string }[]).map((b) => b._type)).toEqual(["section_gallery", "section_rich_text", "section_map"]);
	});

	it("coverage report: layouts, page/post fields, options page values", async () => {
		const paths = workspace("report", DECIDED);
		await run(paths);
		const md = readFileSync(join(paths.reports, "transform", "coverage.md"), "utf8");
		expect(md).toMatch(/\| `page_sections` \| Latest work \(`latest_work`\) \| page about \| 1 \| skipped \(overrides.ts\) \|/);
		expect(md).toMatch(/\| `blocks` \| poll_widget \(`poll_widget`\) \| project city-site \| 1 \| ❌ unmapped \|/);
		expect(md).toMatch(/\| page \| Note above the footer \(`hero_note`\) \| text \| 1: home \| ⚠️ no \| Shown above the footer \|/);
		expect(md).toMatch(/\| post \| Reading time \(`reading_time`\) \| number \| 1: hello \|/);
		expect(md).toMatch(/## ACF options pages[\s\S]*\| Phone \(`phone`\) \| text \| Site settings \| \+1 555 0100 \|/);
		expect(md).toMatch(/\| SMTP password \(`smtp_password`\) \| password \| Site settings \| not carried \(secret\) \|/);
		expect(md).toMatch(/Options rows no field definition describes \(names only\): `options_legacy_banner`/);
		const options = readJson(join(paths.ir, "acf-options.json"));
		expect(options.fields.find((f: { name: string }) => f.name === "social_links").value).toEqual([{ network: "instagram", url: "https://instagram.com/example" }, { network: "linkedin", url: "https://linkedin.com/company/example" }]);
		expect(JSON.stringify(options)).not.toContain("not-read");
	});

	it("options page values not read yet: the report says how to get them", () => {
		const groups = acfGroupsFromExport(fx.fieldDefinitions["acf-project.json"].data, "x");
		const plan = acfOptionsPlan(groups, undefined);
		expect(plan).toMatchObject({ pages: ["site-settings"], valuesRead: false });
		expect(acfReport({ layouts: [], postFields: [], ...(plan ? { options: plan } : {}) }).join("\n")).toMatch(/Values not read:.*import-options/);
		expect(acfOptionsPlan([], undefined)).toBeUndefined();
	});

	it("import-options reads ACF options rows from a database backup, credential-like ones left out", async () => {
		const paths = workspace("dump", undefined, { options: false });
		const r = await importOptions("dump", join(fxDir, "database.sql"), dir);
		expect(r.acfOptions).toBe(5);
		expect(r.dropped).toEqual(expect.arrayContaining(["options_maps_api_key", "options_smtp_password"]));
		const written = readJson(join(paths.raw, "acf-options.json"));
		expect(Object.keys(written.values).sort()).toEqual(["options_footer_text", "options_phone", "options_social_links", "options_social_links_0_network", "options_social_links_0_url"]);
		expect(JSON.stringify(written)).not.toContain("not-read");
	});

	it("overrides accept acfLayouts", () => {
		expect(overridesSchema.safeParse({ acfLayouts: { latest_work: "skip", promo: "cta_banner" } }).success).toBe(true);
		expect(overridesSchema.safeParse({ acfLayouts: { promo: "slider" } }).success).toBe(false);
	});
});
